<?php
declare(strict_types=1);
require_once __DIR__.'/config.php';require_login();require_once __DIR__.'/includes/layout.php';
$user=current_user();$userId=(int)$user['id'];$limit=(int)($user['sodium_personal_account_limit']??0);$unlimited=$limit>=4294967295;
$colors=['#0d6efd'=>'Primary','#6c757d'=>'Secondary','#198754'=>'Success','#dc3545'=>'Danger','#ffc107'=>'Warning','#0dcaf0'=>'Info','#212529'=>'Dark','#6f42c1'=>'Violet','#6610f2'=>'Indigo','#d63384'=>'Rose','#fd7e14'=>'Orange','#20c997'=>'Turquoise','#ffffff'=>'Blanc'];
$csv=static fn(string $value):array=>array_values(array_unique(array_filter(array_map(static fn($item)=>strtolower(trim($item)),explode(',',$value)))));
if($_SERVER['REQUEST_METHOD']==='POST'){
    $action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
    if($action==='delete'){$stmt=$pdo->prepare('SELECT icon_path FROM sodium_mail_accounts WHERE id=? AND created_by_user_id=? AND is_user_managed=1');$stmt->execute([$id,$userId]);$icon=$stmt->fetchColumn();if($icon!==false){$pdo->prepare('DELETE FROM sodium_user_mail_accounts WHERE mail_account_id=?')->execute([$id]);$pdo->prepare('DELETE FROM sodium_mail_accounts WHERE id=? AND created_by_user_id=? AND is_user_managed=1')->execute([$id,$userId]);if($icon&&str_starts_with((string)$icon,'/uploads/mail-icons/'))@unlink(__DIR__.(string)$icon);flash('success','Compte mail supplémentaire supprimé.');}redirect('/mail-accounts.php');}
    $existing=null;if($id){$stmt=$pdo->prepare('SELECT * FROM sodium_mail_accounts WHERE id=? AND created_by_user_id=? AND is_user_managed=1');$stmt->execute([$id,$userId]);$existing=$stmt->fetch();if(!$existing){flash('danger','Compte supplémentaire inaccessible.');redirect('/mail-accounts.php');}}
    $count=$pdo->prepare('SELECT COUNT(*) FROM sodium_mail_accounts WHERE created_by_user_id=? AND is_user_managed=1');$count->execute([$userId]);$used=(int)$count->fetchColumn();
    if(!$id&&(!$unlimited&&($limit<1||$used>=$limit))){flash('danger',$limit<1?'Vous n’êtes pas autorisé à ajouter une adresse mail supplémentaire.':'Vous avez atteint le nombre maximal d’adresses mails supplémentaires autorisées.');redirect('/mail-accounts.php');}
    $email=strtolower(trim((string)($_POST['email_address']??'')));$domain=strtolower((string)substr(strrchr($email,'@')?:'',1));if(!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('danger','Adresse mail invalide.');redirect('/mail-accounts.php');}
    $exists=$pdo->prepare('SELECT COUNT(*) FROM sodium_mail_accounts WHERE LOWER(email_address)=? AND id<>?');$exists->execute([$email,$id]);if($exists->fetchColumn()){flash('warning','Ce compte existe déjà dans Sodium. Contactez l’administrateur pour demander son utilisation.');redirect('/mail-accounts.php');}
    $banned=$pdo->prepare('SELECT COUNT(*) FROM sodium_banned_mail_addresses WHERE email_address=?');$banned->execute([$email]);if($banned->fetchColumn()||in_array($domain,$csv((string)($user['sodium_personal_excluded_domains']??'')),true)||in_array($email,$csv((string)($user['sodium_personal_excluded_addresses']??'')),true)){flash('danger','Cette adresse ou ce domaine n’est pas autorisé.');redirect('/mail-accounts.php');}
    $password=(string)($_POST['password']??'');if(!$id&&$password===''){flash('danger','Le mot de passe est obligatoire.');redirect('/mail-accounts.php');}
    $iconPath=(string)($existing['icon_path']??'');if(!empty($_FILES['icon']['tmp_name'])&&is_uploaded_file($_FILES['icon']['tmp_name'])){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['icon']['tmp_name']);$info=@getimagesize($_FILES['icon']['tmp_name']);$extensions=['image/png'=>'png','image/webp'=>'webp'];if(!isset($extensions[$mime])||($info['mime']??'')!==$mime||(int)$_FILES['icon']['size']>2*1024*1024){flash('danger','Icône invalide : PNG ou WebP de 2 Mo maximum.');redirect('/mail-accounts.php');}$filename=bin2hex(random_bytes(12)).'.'.$extensions[$mime];if(!move_uploaded_file($_FILES['icon']['tmp_name'],__DIR__.'/uploads/mail-icons/'.$filename)){flash('danger','Enregistrement de l’icône impossible.');redirect('/mail-accounts.php');}$iconPath='/uploads/mail-icons/'.$filename;}
    $encryption=static fn(string $value):string=>in_array($value,['ssl','tls','none'],true)?$value:'ssl';$status=($_POST['account_status']??'active')==='inactive'?'inactive':'active';$color=array_key_exists((string)($_POST['label_color']??''),$colors)?(string)$_POST['label_color']:'#0d6efd';
    $values=[$email,trim((string)($_POST['display_name']??'')),trim((string)($_POST['imap_host']??''))?:'localhost',max(1,min(65535,(int)($_POST['imap_port']??993))),$encryption((string)($_POST['imap_encryption']??'ssl')),trim((string)($_POST['smtp_host']??''))?:'localhost',max(1,min(65535,(int)($_POST['smtp_port']??465))),$encryption((string)($_POST['smtp_encryption']??'ssl')),trim((string)($_POST['login_name']??''))?:$email,$status,mb_substr(trim((string)($_POST['label_text']??'')),0,60),$color,$iconPath];
    try{if($id){$sql='UPDATE sodium_mail_accounts SET email_address=?,display_name=?,imap_host=?,imap_port=?,imap_encryption=?,smtp_host=?,smtp_port=?,smtp_encryption=?,login_name=?,account_status=?,label_text=?,label_color=?,icon_path=?'.($password!==''?',password_cipher=?':'').' WHERE id=? AND created_by_user_id=? AND is_user_managed=1';if($password!=='')$values[]=sodium_encrypt_secret($password);array_push($values,$id,$userId);$pdo->prepare($sql)->execute($values);flash('success','Compte mail supplémentaire modifié.');}else{$pdo->beginTransaction();$values[]=sodium_encrypt_secret($password);array_push($values,$userId);$pdo->prepare('INSERT INTO sodium_mail_accounts(email_address,display_name,imap_host,imap_port,imap_encryption,smtp_host,smtp_port,smtp_encryption,login_name,account_status,label_text,label_color,icon_path,password_cipher,created_by_user_id,is_user_managed) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1)')->execute($values);$newId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO sodium_user_mail_accounts(user_id,mail_account_id,can_read,can_send,can_manage,is_default) VALUES(?,?,1,1,1,0)')->execute([$userId,$newId]);$pdo->commit();flash('success','Compte mail supplémentaire ajouté.');}}catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();error_log('[Sodium additional account] '.$error->getMessage());flash('danger','Le compte n’a pas pu être enregistré.');}redirect('/mail-accounts.php');
}
$assigned=$pdo->prepare('SELECT a.* FROM sodium_mail_accounts a JOIN sodium_user_mail_accounts ua ON ua.mail_account_id=a.id WHERE ua.user_id=? AND (a.is_user_managed=0 OR a.created_by_user_id<>?) ORDER BY a.display_name,a.email_address');$assigned->execute([$userId,$userId]);$assigned=$assigned->fetchAll();$personal=$pdo->prepare('SELECT * FROM sodium_mail_accounts WHERE created_by_user_id=? AND is_user_managed=1 ORDER BY display_name,email_address');$personal->execute([$userId]);$personal=$personal->fetchAll();$canAdd=$unlimited||($limit>count($personal));
$blank=['id'=>0,'email_address'=>'','display_name'=>'','login_name'=>'','label_text'=>'','label_color'=>'#0d6efd','icon_path'=>'','account_status'=>'active','imap_host'=>'localhost','imap_port'=>993,'imap_encryption'=>'ssl','smtp_host'=>'localhost','smtp_port'=>465,'smtp_encryption'=>'ssl'];$accountCards=[['Comptes attribués par l’administrateur',$assigned,false]];if($limit>0)$accountCards[]=['Mes comptes mails supplémentaires',$personal,true];
sodium_render_header('Comptes mails');
?>
<?php foreach($accountCards as [$title,$rows,$mine]):?><div class="table-card mb-4"><div class="p-3 border-bottom d-flex align-items-center justify-content-between gap-3"><div><h2 class="h6 mb-1"><?=e($title)?></h2><?php if($mine):?><span class="badge text-bg-light"><?=count($personal)?> / <?=$unlimited?'Illimité':$limit?> utilisés</span><?php endif;?></div><?php if($mine&&$canAdd):?><button class="btn btn-danger btn-sm" data-bs-toggle="modal" data-bs-target="#additionalAccount0"><i class="bi bi-plus-lg"></i> Ajouter</button><?php endif;?></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Compte</th><th>Label</th><th>Statut</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="4" class="text-center text-muted py-4">Aucun compte.</td></tr><?php endif;?><?php foreach($rows as $account):?><tr><td><span class="d-flex align-items-center gap-2"><?php if($account['icon_path']):?><img class="mail-account-image" style="--account-color:<?=e($account['label_color'])?>" src="<?=e($account['icon_path'])?>" alt=""><?php endif;?><span><strong><?=e($account['display_name']?:$account['email_address'])?></strong><small class="d-block text-muted"><?=e($account['email_address'])?></small></span></span></td><td><?php if($account['label_text']):?><span class="mailbox-label" style="--label-color:<?=e($account['label_color'])?>;--label-text-color:<?=e(sodium_color_contrast((string)$account['label_color']))?>"><?=e($account['label_text'])?></span><?php else:?>—<?php endif;?></td><td><span class="badge text-bg-<?=$account['account_status']==='active'?'success':'secondary'?>"><?=$account['account_status']==='active'?'Actif':'Inactif'?></span> <span class="badge text-bg-<?=empty($account['last_error'])?'success':'danger'?>"><?=empty($account['last_error'])?'Connecté':'À vérifier'?></span></td><td class="text-end"><?php if($mine):?><div class="btn-group btn-group-sm"><button class="btn btn-outline-secondary" data-bs-toggle="modal" data-bs-target="#additionalAccount<?=(int)$account['id']?>"><i class="bi bi-pencil"></i> Modifier</button><form method="post" onsubmit="return confirm('Supprimer ce compte mail supplémentaire ?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$account['id']?>"><button class="btn btn-outline-danger"><i class="bi bi-trash"></i></button></form></div><?php else:?><span class="text-muted"><i class="bi bi-lock"></i> Géré par l’administrateur</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php endforeach;?>
<?php foreach(array_merge([$blank],$personal) as $account):$isNew=empty($account['id']);?><div class="modal fade" id="additionalAccount<?=(int)$account['id']?>" tabindex="-1" data-bs-backdrop="static" data-bs-keyboard="false"><div class="modal-dialog modal-lg modal-dialog-scrollable"><form class="modal-content" method="post" enctype="multipart/form-data"><div class="modal-header"><h2 class="modal-title h5"><?=$isNew?'Ajouter':'Modifier'?> un compte mail supplémentaire</h2><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)$account['id']?>"><div class="row g-3"><div class="col-md-7"><label class="form-label">Adresse mail</label><input class="form-control" type="email" name="email_address" value="<?=e($account['email_address'])?>" required></div><div class="col-md-5"><label class="form-label">Nom affiché</label><input class="form-control" name="display_name" value="<?=e($account['display_name'])?>"></div><div class="col-md-6"><label class="form-label">Identifiant IMAP/SMTP</label><input class="form-control" name="login_name" value="<?=e($account['login_name'])?>" placeholder="Par défaut : adresse mail"></div><div class="col-md-6"><label class="form-label">Mot de passe</label><input class="form-control" type="password" name="password" autocomplete="new-password" placeholder="<?=$isNew?'Obligatoire':'Laisser vide pour conserver'?>" <?=$isNew?'required':''?>></div><div class="col-md-4"><label class="form-label">Texte du label</label><input class="form-control" name="label_text" value="<?=e($account['label_text'])?>"></div><div class="col-md-8"><label class="form-label">Couleur de fond de l’icône</label><div class="account-color-palette"><?php foreach($colors as $color=>$name):?><label class="account-color-choice" title="<?=e($name)?>"><input type="radio" name="label_color" value="<?=e($color)?>" <?=strtolower((string)$account['label_color'])===strtolower($color)?'checked':''?>><span style="--swatch-color:<?=e($color)?>"></span></label><?php endforeach;?></div></div><div class="col-md-8"><label class="form-label">Icône du compte</label><input class="form-control" type="file" name="icon" accept="image/png,image/webp,.png,.webp"><div class="form-text">PNG ou WebP — 2 Mo maximum.</div></div><div class="col-md-4"><label class="form-label">Statut</label><select class="form-select" name="account_status"><option value="active" <?=$account['account_status']==='active'?'selected':''?>>Actif</option><option value="inactive" <?=$account['account_status']==='inactive'?'selected':''?>>Inactif</option></select></div><div class="col-12"><hr><h3 class="h6">Réception IMAP</h3></div><div class="col-md-6"><label class="form-label">Serveur</label><input class="form-control" name="imap_host" value="<?=e($account['imap_host'])?>" required></div><div class="col-md-3"><label class="form-label">Port</label><input class="form-control" type="number" name="imap_port" value="<?=(int)$account['imap_port']?>" min="1" max="65535" required></div><div class="col-md-3"><label class="form-label">Sécurité</label><select class="form-select" name="imap_encryption"><?php foreach(['ssl'=>'SSL','tls'=>'TLS','none'=>'Aucune'] as $key=>$label):?><option value="<?=$key?>" <?=$account['imap_encryption']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-12"><hr><h3 class="h6">Envoi SMTP</h3></div><div class="col-md-6"><label class="form-label">Serveur</label><input class="form-control" name="smtp_host" value="<?=e($account['smtp_host'])?>" required></div><div class="col-md-3"><label class="form-label">Port</label><input class="form-control" type="number" name="smtp_port" value="<?=(int)$account['smtp_port']?>" min="1" max="65535" required></div><div class="col-md-3"><label class="form-label">Sécurité</label><select class="form-select" name="smtp_encryption"><?php foreach(['ssl'=>'SSL','tls'=>'TLS','none'=>'Aucune'] as $key=>$label):?><option value="<?=$key?>" <?=$account['smtp_encryption']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div></div><div class="alert alert-info mt-3 mb-0"><i class="bi bi-shield-lock"></i> Le mot de passe est chiffré en AES-256-GCM.</div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Annuler</button><button class="btn btn-danger">Enregistrer</button></div></form></div></div></div><?php endforeach;?>
